import {quizIcon} from './icons.js';
import {describeAxisPosition} from './axis-presentation.js';
import {ideologyDescription,esc} from './result-presentation.js';
import {readingModels} from './insights.js';
import {rankCountries} from './countries.js';
import {portraitStyle} from './portrait.js';
import {renderPersonDetails} from './person-details.js';
export const POSTER_COLORS=['#e2b668','#74d2c5','#91b4ef','#c5a1e9','#eb9eaa','#c4a6ef','#80c8e6','#87bce8','#e9b186','#eab883','#94aaf0','#8edbb2'];
export function posterModel(profile,axes,ranking,countryMode='current'){
 return {ideology:ideologyDescription(readingModels(profile)[0]),lead:ranking[0],nearby:ranking.slice(1,4),countries:rankCountries(profile,countryMode).slice(0,3),positions:axes.map((a,i)=>({axis:a,value:profile[i],reading:describeAxisPosition(a,profile[i]),color:POSTER_COLORS[i]}))};
}
export function renderResultPoster({profile,axes,ranking,photos,countryMode='current'}){
 const m=posterModel(profile,axes,ranking,countryMode),photo=photos[m.lead.entity.id];
 const portrait=photo?`<figure class="portrait">${photo.crop?`<span class="portrait-window" style="${portraitStyle(photo)}">`:''}<img class="${photo.preserveColor?'preserve-color':''}" src="${esc(photo.src)}" alt="Retrato de ${esc(m.lead.entity.name)}" width="200" height="240">${photo.crop?'</span>':''}</figure>`:'';
 return `<div class="card-device-preview"><div class="card-live-preview result-poster"><header class="poster-header"><strong>UruguayCompass</strong><span>MI RESULTADO</span></header><h3 class="poster-ideology">${esc(m.ideology.name)}</h3><div class="poster-main"><div class="card-preview-person">${portrait}<strong class="poster-affinity">${m.lead.score}%</strong><span class="poster-label">AFINIDAD ESTIMADA</span><h4>${esc(m.lead.entity.name)}</h4>${renderPersonDetails(m.lead.entity)}<p class="small">${m.lead.entity.hypothesisCount||0} hipótesis muy inciertas</p></div><div class="card-preview-axes"><h4>TUS 12 EJES</h4>${m.positions.map(x=>`<div style="--poster-accent:${x.color}"><span class="poster-axis-icon" aria-hidden="true">${quizIcon(x.axis.slug)}</span><span class="poster-axis-name" title="${esc(x.reading.label)}">${esc(x.reading.side?x.axis[x.reading.side]:x.axis.short)}</span><span class="poster-axis-track"><i style="width:${x.reading.percent??50}%"></i></span><strong>${x.reading.percent===null?'—':x.reading.percent+'%'}</strong></div>`).join('')}</div></div><div class="poster-bottom"><div><h4>OTRAS REFERENCIAS</h4><ul>${m.nearby.map(x=>`<li><span>${esc(x.entity.name)}</span><strong>${x.score}%</strong></li>`).join('')}</ul></div><div class="card-preview-countries"><h4>PAÍSES ${countryMode==='current'?'ACTUALES':'HISTÓRICOS'}</h4><ul>${m.countries.map(x=>`<li><span>${esc(countryMode==='current'?x.entity.flag||'':'')} ${esc(x.entity.name)}</span><strong>${x.score}%</strong></li>`).join('')}</ul></div></div><footer class="poster-footer"><a href="https://uruguaycompass.cc">DESCUBRÍ TU PERFIL<br>URUGUAYCOMPASS.CC</a><img src="site-qr.svg" width="54" height="54" alt="Código QR para abrir UruguayCompass"></footer><p class="poster-credit">—: equilibrado. Personajes: 12 ejes; incluye hipótesis muy inciertas. Países: 3 ejes constitucionales. Educativo; no recomienda un voto.</p></div></div>`;
}
